import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as n,o as a,af as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"SFT (Bridge)","description":"Engineering-decision bridge for supervised fine-tuning: when prompt and RAG are not enough and labeled data must move weights, with a data/cost/latency/maintenance impact table.","frontmatter":{"title":"SFT (Bridge)","description":"Engineering-decision bridge for supervised fine-tuning: when prompt and RAG are not enough and labeled data must move weights, with a data/cost/latency/maintenance impact table.","domain":"tech","tags":["tech","training","bridge","sft"],"navOrder":141,"topicId":"model-lifecycle-sft","layer":"1","status":"bridge","nodeType":"boundary","owner":"learn-ai","externalOwners":[{"site":"llm","url":"https://llm.zenheart.site/"}],"lastVerified":"2026-09-01","listed":true},"headers":[],"relativePath":"tech/01-model-lifecycle/post-training/sft.md","filePath":"tech/01-model-lifecycle/post-training/sft.md","lastUpdated":1791166440000}'),r={name:"tech/01-model-lifecycle/post-training/sft.md"};function o(s,e,l,d,g,c){return a(),n("div",null,[...e[0]||(e[0]=[i('<blockquote><p><strong>Group</strong>: Model Lifecycle (bridge) | <strong>Previous group exit</strong>: inference fundamentals and interface contracts | <strong>This page exit</strong>: know when to change weights instead of prompts or retrieval</p></blockquote><h1 id="sft-bridge" tabindex="-1">SFT (Bridge) <a class="header-anchor" href="#sft-bridge" aria-label="Permalink to &quot;SFT (Bridge)&quot;">​</a></h1><blockquote><p><strong>Bridge page</strong>: this page answers only the engineering-decision question. Training objectives, loss functions and data recipes are derived in <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a> (SFT chapter).</p></blockquote><h2 id="what-problem-it-solves" tabindex="-1">What problem it solves <a class="header-anchor" href="#what-problem-it-solves" aria-label="Permalink to &quot;What problem it solves&quot;">​</a></h2><p><strong>Supervised Fine-Tuning (SFT)</strong>: take an existing pretrained model and continue training it on your <code>input → expected output</code> labeled pairs, making it specialized for a domain, format, or style. It changes <strong>model weights</strong> — a different road from prompt engineering (changeable per call, zero training cost) and RAG (external knowledge base, model untouched).</p><p>What SFT is good at:</p><ul><li><strong>Domain language</strong>: terminology-dense fields such as medicine and law.</li><li><strong>Stable output format</strong>: always producing the same JSON shape or code skeleton, more reliably than prompt constraints.</li><li><strong>Style and tone</strong>: brand writing style, a consistent response personality.</li><li><strong>Smaller model, lower cost</strong>: distill general-model capability into a smaller, faster, cheaper specialized model.</li></ul><p>What SFT is bad at (use mainline solutions):</p><ul><li><strong>Frequently changing knowledge</strong> (catalogs, news) → <a href="./../../04-grounding/rag.html">RAG</a>; update the index, take effect immediately.</li><li><strong>One-off format constraints</strong> → <a href="./../../02-inference-interface/structured-output.html">structured output</a> + prompt; live in minutes.</li><li><strong>Prototype stage</strong> → any training investment here is premature optimization.</li></ul><h2 id="when-prompt-and-rag-are-not-enough" tabindex="-1">When prompt and RAG are not enough <a class="header-anchor" href="#when-prompt-and-rag-are-not-enough" aria-label="Permalink to &quot;When prompt and RAG are not enough&quot;">​</a></h2><p>Put SFT on the agenda only when all of the following hold (any miss sends you back to the mainline):</p><ol><li><strong>Prompt and few-shot exhausted</strong>: format instability and style drift cannot be fixed at the prompt layer.</li><li><strong>RAG optimized</strong>: hybrid retrieval, reranking, and chunk tuning done; accuracy still short, and the bottleneck is confirmed as &quot;the model cannot express this domain&quot; rather than &quot;retrieval misses&quot;.</li><li><strong>A meaningful volume of high-quality labeled data</strong>: hundreds to tens of thousands of real input/output pairs (order of magnitude, <strong>unverified</strong> — thresholds vary enormously by task and model; run small experiments first).</li><li><strong>Budget and ML expertise</strong>: training, evaluation, and regression testing form a continuous pipeline, not a one-off action.</li></ol><h2 id="decision-impact-table" tabindex="-1">Decision impact table <a class="header-anchor" href="#decision-impact-table" aria-label="Permalink to &quot;Decision impact table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Prompt</th><th>RAG</th><th>SFT</th></tr></thead><tbody><tr><td><strong>Data requirement</strong></td><td>None (write the prompt)</td><td>Unstructured docs suffice</td><td>High-quality labeled pairs at scale (unverified)</td></tr><tr><td><strong>Cost structure</strong></td><td>Inference only</td><td>Inference + retrieval infra</td><td>Training compute + labeling + eval pipeline (vendor pricing applies; this repo cites no specific figures)</td></tr><tr><td><strong>Time to effect</strong></td><td>Immediate</td><td>Immediate (re-index)</td><td>Requires retraining to update</td></tr><tr><td><strong>Inference latency</strong></td><td>Unchanged</td><td>Adds retrieval overhead</td><td>No retrieval overhead after training; a smaller model can cut latency</td></tr><tr><td><strong>Maintenance burden</strong></td><td>Low</td><td>Medium (data freshness)</td><td>High (data versions, model versions, regression evals)</td></tr><tr><td><strong>Debuggability</strong></td><td>High (read the prompt)</td><td>High (inspect retrieval hits)</td><td>Low (weights are unreadable; eval sets speak)</td></tr></tbody></table><h2 id="managed-fine-tuning-services" tabindex="-1">Managed fine-tuning services <a class="header-anchor" href="#managed-fine-tuning-services" aria-label="Permalink to &quot;Managed fine-tuning services&quot;">​</a></h2><p>If SFT is confirmed, prefer managed services over a self-built GPU pipeline: OpenAI Fine-Tuning, Azure OpenAI, Together AI, Anyscale and others offer fine-tuning APIs. <strong>Note</strong>: even with managed services, data preparation, effect evaluation, and knowing when to stop training still require ML judgment; an app engineer&#39;s role is to collaborate with ML engineers and consume the trained artifact through APIs.</p><h2 id="pre-upgrade-checklist" tabindex="-1">Pre-upgrade checklist <a class="header-anchor" href="#pre-upgrade-checklist" aria-label="Permalink to &quot;Pre-upgrade checklist&quot;">​</a></h2><p>Before proposing &quot;let&#39;s do SFT&quot;, tick every item; any unticked item sends you back to its layer first:</p><ul><li>[ ] Format problems already attacked with schema validation + few-shot (L1 <a href="./../../02-inference-interface/structured-output.html">structured output</a>)</li><li>[ ] Knowledge problems already attacked with hybrid retrieval + reranking + chunk tuning (L3 <a href="./../../04-grounding/advanced-retrieval.html">advanced retrieval</a>)</li><li>[ ] At least two or three models compared, ruling out the cheaper explanation of &quot;wrong model chosen&quot; (L5 <a href="./../../08-production/cost-performance.html">cost &amp; performance</a>)</li><li>[ ] Labeled data actually exists with inspectable quality — not &quot;theoretically we could have people label&quot;</li><li>[ ] A rollback path exists if post-training quality drops (back to the prompt + RAG version)</li><li>[ ] An ML engineer or managed service owns training and evaluation — not a frontend engineer self-teaching on production</li></ul><h2 id="common-anti-patterns" tabindex="-1">Common anti-patterns <a class="header-anchor" href="#common-anti-patterns" aria-label="Permalink to &quot;Common anti-patterns&quot;">​</a></h2><ul><li><strong>&quot;Fine-tune it and see&quot;</strong>: treating the most expensive lever as the experimental one. The correct order is cheapest first — each higher layer&#39;s debugging cost is an order of magnitude lower.</li><li><strong>Chasing knowledge with SFT</strong>: pouring catalogs and FAQs into the training set. Knowledge changes force retraining; this is the textbook RAG scenario.</li><li><strong>Vibes over evaluation</strong>: &quot;feels smoother after training&quot; is not evidence. Pre/post comparison must run through eval sets (<a href="./../../08-production/evaluation.html">Evaluation (bridge)</a>).</li><li><strong>Padding data with generation</strong>: generating training data with the model itself amplifies existing biases; human verification cannot be skipped.</li></ul><h2 id="deep-derivations-and-implementation" tabindex="-1">Deep derivations and implementation <a class="header-anchor" href="#deep-derivations-and-implementation" aria-label="Permalink to &quot;Deep derivations and implementation&quot;">​</a></h2><ul><li>Training objectives, data recipes, hyperparameter choices → the SFT chapter of <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a>.</li><li>Mainline next steps: return to <a href="./../../04-grounding/rag.html">RAG</a> and <a href="./../../08-production/evaluation.html">Evaluation (bridge)</a> — &quot;SFT works better&quot; must be backed by evaluation evidence, not vibes.</li></ul>',23)])])}const b=t(r,[["render",o]]);export{f as __pageData,b as default};
